"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[876],{8810:e=>{e.exports=JSON.parse('{"archive":{"blogPosts":[{"id":"welcome","metadata":{"permalink":"/eds-multi-brand-docs/blog/welcome","source":"@site/blog/2021-08-26-welcome/index.md","title":"Welcome to AEM Multi-Brand Documentation","description":"Welcome to the AEM Multi-Brand project documentation! This site provides comprehensive developer documentation for building and managing multi-brand experiences with Adobe Experience Manager.","date":"2021-08-26T00:00:00.000Z","tags":[{"inline":false,"label":"AEM","permalink":"/eds-multi-brand-docs/blog/tags/aem","description":"Adobe Experience Manager related content"},{"inline":false,"label":"Multi-Brand","permalink":"/eds-multi-brand-docs/blog/tags/multi-brand","description":"Multi-brand architecture and implementation"},{"inline":false,"label":"Documentation","permalink":"/eds-multi-brand-docs/blog/tags/documentation","description":"Documentation and guides"},{"inline":false,"label":"Welcome","permalink":"/eds-multi-brand-docs/blog/tags/welcome","description":"Welcome and introduction posts"}],"readingTime":0.88,"hasTruncateMarker":true,"authors":[{"name":"Adobe Team","title":"Adobe Experience Manager Development Team","url":"https://adobe.com","page":{"permalink":"/eds-multi-brand-docs/blog/authors/adobe-team"},"socials":{"x":"https://x.com/adobe","linkedin":"https://www.linkedin.com/in/adobe/","github":"https://github.com/adobe","website":"https://adobe.com"},"imageURL":"https://github.com/adobe.png","key":"adobe-team"}],"frontMatter":{"slug":"welcome","title":"Welcome to AEM Multi-Brand Documentation","authors":["adobe-team"],"tags":["aem","multi-brand","documentation","welcome"]},"unlisted":false,"nextItem":{"title":"Interactive Documentation with MDX","permalink":"/eds-multi-brand-docs/blog/mdx-blog-post"}},"content":"Welcome to the AEM Multi-Brand project documentation! This site provides comprehensive developer documentation for building and managing multi-brand experiences with Adobe Experience Manager.\\n\\n\x3c!-- truncate --\x3e\\n\\n## What You\'ll Find Here\\n\\nThis documentation covers:\\n\\n- **Getting Started**: Quick setup and installation guides\\n- **Theme Management**: How to create and manage brand themes\\n- **Blocks**: Reusable UI components for your projects\\n- **Deployment**: How to deploy your multi-brand applications\\n\\n## Project Structure\\n\\nThe AEM Multi-Brand project is organized to support multiple brands with shared components and brand-specific customizations. Each brand can have its own theme while sharing common functionality.\\n\\n## Getting Started\\n\\nTo get started with the AEM Multi-Brand project:\\n\\n1. **Install dependencies**: `npm install`\\n2. **Initialize a new theme**: `npm run scaffold:create`\\n3. **Start development**: `npm start`\\n\\n## Contributing\\n\\nWe welcome contributions! Please create an issue or submit a pull request on GitHub for any improvements or bug reports.\\n\\n## Support\\n\\n- **Documentation Issues**: Create an issue in this repository\\n- **AEM Questions**: Check [Stack Overflow](https://stackoverflow.com/questions/tagged/aem)\\n- **Community**: Join our [Discord](https://discordapp.com/invite/aem) community\\n\\nHappy coding! \ud83d\ude80"},{"id":"mdx-blog-post","metadata":{"permalink":"/eds-multi-brand-docs/blog/mdx-blog-post","source":"@site/blog/2021-08-01-mdx-blog-post.mdx","title":"Interactive Documentation with MDX","description":"This blog post demonstrates how to use MDX (Markdown + JSX) to create interactive documentation for the EDS Multi-Brand project.","date":"2021-08-01T00:00:00.000Z","tags":[{"inline":false,"label":"AEM","permalink":"/eds-multi-brand-docs/blog/tags/aem","description":"Adobe Experience Manager related content"},{"inline":false,"label":"MDX","permalink":"/eds-multi-brand-docs/blog/tags/mdx","description":"MDX and interactive documentation"},{"inline":false,"label":"Documentation","permalink":"/eds-multi-brand-docs/blog/tags/documentation","description":"Documentation and guides"},{"inline":false,"label":"Interactive","permalink":"/eds-multi-brand-docs/blog/tags/interactive","description":"Interactive documentation features"}],"readingTime":0.74,"hasTruncateMarker":true,"authors":[{"name":"Adobe Team","title":"Adobe Experience Manager Development Team","url":"https://adobe.com","page":{"permalink":"/eds-multi-brand-docs/blog/authors/adobe-team"},"socials":{"x":"https://x.com/adobe","linkedin":"https://www.linkedin.com/in/adobe/","github":"https://github.com/adobe","website":"https://adobe.com"},"imageURL":"https://github.com/adobe.png","key":"adobe-team"}],"frontMatter":{"slug":"mdx-blog-post","title":"Interactive Documentation with MDX","authors":["adobe-team"],"tags":["aem","mdx","documentation","interactive"]},"unlisted":false,"prevItem":{"title":"Welcome to AEM Multi-Brand Documentation","permalink":"/eds-multi-brand-docs/blog/welcome"},"nextItem":{"title":"Deep Dive: Multi-Brand Architecture","permalink":"/eds-multi-brand-docs/blog/long-blog-post"}},"content":"This blog post demonstrates how to use MDX (Markdown + JSX) to create interactive documentation for the EDS Multi-Brand project.\\n\\nBlog posts support [Docusaurus Markdown features](https://docusaurus.io/docs/markdown-features), such as [MDX](https://mdxjs.com/).\\n\\n:::tip\\n\\nUse the power of React to create interactive documentation components.\\n\\n:::\\n\\n{/* truncate */}\\n\\n## Interactive Components\\n\\nYou can use JSX to create interactive components in your documentation. For example, here\'s an interactive theme preview:\\n\\n```jsx\\n<button onClick={() => alert(\'Theme preview clicked!\')}>Preview Theme</button>\\n```\\n\\n<button onClick={() => alert(\'Theme preview clicked!\')}>Preview Theme</button>\\n\\n## Benefits of MDX\\n\\n- **Interactive examples**: Embed working components in documentation\\n- **Dynamic content**: Create responsive documentation\\n- **Better engagement**: Keep readers engaged with interactive elements\\n- **Code examples**: Show live code examples with working demos\\n\\n## Use Cases for EDS Multi-Brand\\n\\n- Theme configuration wizards\\n- Component preview tools\\n- Brand switching demos\\n- Interactive tutorials\\n\\nThis makes our documentation more engaging and helps developers understand concepts faster!"},{"id":"long-blog-post","metadata":{"permalink":"/eds-multi-brand-docs/blog/long-blog-post","source":"@site/blog/2019-05-29-long-blog-post.md","title":"Deep Dive: Multi-Brand Architecture","description":"This is a comprehensive guide to the EDS Multi-Brand architecture and implementation details.","date":"2019-05-29T00:00:00.000Z","tags":[{"inline":false,"label":"AEM","permalink":"/eds-multi-brand-docs/blog/tags/aem","description":"Adobe Experience Manager related content"},{"inline":false,"label":"Architecture","permalink":"/eds-multi-brand-docs/blog/tags/architecture","description":"Technical architecture discussions"},{"inline":false,"label":"Multi-Brand","permalink":"/eds-multi-brand-docs/blog/tags/multi-brand","description":"Multi-brand architecture and implementation"},{"inline":false,"label":"Technical","permalink":"/eds-multi-brand-docs/blog/tags/technical","description":"Technical deep dives and tutorials"}],"readingTime":1.52,"hasTruncateMarker":true,"authors":[{"name":"Adobe Team","title":"Adobe Experience Manager Development Team","url":"https://adobe.com","page":{"permalink":"/eds-multi-brand-docs/blog/authors/adobe-team"},"socials":{"x":"https://x.com/adobe","linkedin":"https://www.linkedin.com/in/adobe/","github":"https://github.com/adobe","website":"https://adobe.com"},"imageURL":"https://github.com/adobe.png","key":"adobe-team"}],"frontMatter":{"slug":"long-blog-post","title":"Deep Dive: Multi-Brand Architecture","authors":["adobe-team"],"tags":["aem","architecture","multi-brand","technical"]},"unlisted":false,"prevItem":{"title":"Interactive Documentation with MDX","permalink":"/eds-multi-brand-docs/blog/mdx-blog-post"},"nextItem":{"title":"EDS Multi-Brand Project Launch","permalink":"/eds-multi-brand-docs/blog/first-blog-post"}},"content":"This is a comprehensive guide to the EDS Multi-Brand architecture and implementation details.\\n\\nUse a `\x3c!--` `truncate` `--\x3e` comment to limit blog post size in the list view.\\n\\n\x3c!-- truncate --\x3e\\n\\n## Architecture Overview\\n\\nThe EDS Multi-Brand project is built on a foundation of shared components and brand-specific theming. This architecture allows for maximum code reuse while maintaining brand differentiation.\\n\\n## Core Principles\\n\\n### 1. Shared Component Library\\n\\nAll brands share a common component library that provides consistent functionality across different brand experiences. This includes:\\n\\n- Navigation components\\n- Content blocks\\n- Interactive elements\\n- Form components\\n\\n### 2. Brand-Specific Theming\\n\\nEach brand can have its own theme that customizes the appearance of shared components. Themes include:\\n\\n- Color palettes\\n- Typography\\n- Spacing and layout\\n- Brand-specific assets\\n\\n### 3. Configuration-Driven Development\\n\\nThe project uses configuration files to define brand-specific settings, making it easy to add new brands without code changes.\\n\\n## Implementation Details\\n\\n### Theme System\\n\\nThe theme system uses CSS custom properties to define brand variables:\\n\\n```css\\n:root {\\n  --brand-primary: #007bff;\\n  --brand-secondary: #6c757d;\\n  --brand-accent: #28a745;\\n}\\n```\\n\\n### Component Structure\\n\\nEach component follows a consistent structure:\\n\\n```\\nblocks/\\n\u251c\u2500\u2500 component-name/\\n\u2502   \u251c\u2500\u2500 component-name.css\\n\u2502   \u251c\u2500\u2500 component-name.js\\n\u2502   \u2514\u2500\u2500 block-config.js\\n```\\n\\n### Brand Configuration\\n\\nBrands are configured through environment variables and configuration files:\\n\\n```javascript\\n// Brand configuration\\nconst brands = {\\n  brand1: {\\n    name: \'Brand One\',\\n    theme: \'brand1-theme\',\\n    assets: \'/brand1/assets\'\\n  }\\n};\\n```\\n\\n## Best Practices\\n\\n1. **Always use shared components** when possible\\n2. **Keep brand-specific code minimal**\\n3. **Test across all brands** during development\\n4. **Document brand requirements** clearly\\n5. **Use semantic HTML** for accessibility\\n\\n## Performance Considerations\\n\\n- Shared components are cached across brands\\n- Brand-specific assets are loaded on demand\\n- CSS is optimized for each brand\\n- JavaScript is bundled efficiently\\n\\n## Future Enhancements\\n\\nWe\'re planning several enhancements to the multi-brand system:\\n\\n- Advanced theming capabilities\\n- Brand-specific component variants\\n- Automated brand testing\\n- Enhanced performance optimizations\\n\\nStay tuned for more technical deep dives and implementation guides!"},{"id":"first-blog-post","metadata":{"permalink":"/eds-multi-brand-docs/blog/first-blog-post","source":"@site/blog/2019-05-28-first-blog-post.md","title":"EDS Multi-Brand Project Launch","description":"We\'re excited to announce the launch of the EDS Multi-Brand project! This project provides a comprehensive solution for managing multiple brands within Adobe Experience Manager.","date":"2019-05-28T00:00:00.000Z","tags":[{"inline":false,"label":"AEM","permalink":"/eds-multi-brand-docs/blog/tags/aem","description":"Adobe Experience Manager related content"},{"inline":false,"label":"Multi-Brand","permalink":"/eds-multi-brand-docs/blog/tags/multi-brand","description":"Multi-brand architecture and implementation"},{"inline":false,"label":"Launch","permalink":"/eds-multi-brand-docs/blog/tags/launch","description":"Project launch announcements"},{"inline":false,"label":"Announcement","permalink":"/eds-multi-brand-docs/blog/tags/announcement","description":"Project announcements"}],"readingTime":0.48,"hasTruncateMarker":true,"authors":[{"name":"Adobe Team","title":"Adobe Experience Manager Development Team","url":"https://adobe.com","page":{"permalink":"/eds-multi-brand-docs/blog/authors/adobe-team"},"socials":{"x":"https://x.com/adobe","linkedin":"https://www.linkedin.com/in/adobe/","github":"https://github.com/adobe","website":"https://adobe.com"},"imageURL":"https://github.com/adobe.png","key":"adobe-team"}],"frontMatter":{"slug":"first-blog-post","title":"EDS Multi-Brand Project Launch","authors":["adobe-team"],"tags":["aem","multi-brand","launch","announcement"]},"unlisted":false,"prevItem":{"title":"Deep Dive: Multi-Brand Architecture","permalink":"/eds-multi-brand-docs/blog/long-blog-post"}},"content":"We\'re excited to announce the launch of the EDS Multi-Brand project! This project provides a comprehensive solution for managing multiple brands within Adobe Experience Manager.\\n\\n\x3c!-- truncate --\x3e\\n\\nThe EDS Multi-Brand project enables developers to create and manage multiple brand experiences from a single codebase. With shared components and brand-specific theming, you can maintain consistency while allowing for brand differentiation.\\n\\nKey features include:\\n\\n- **Multi-brand theming system**\\n- **Shared component library**\\n- **Brand-specific customizations**\\n- **Automated deployment workflows**\\n\\nStay tuned for more updates and detailed documentation on how to get started with the EDS Multi-Brand project!"}]}}')}}]);